/** Records a stored claim edit: CLAIM_EDITED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>. */
public class AuditClaimEdited {
    public void audit(@Val ClaimInput input, @Val Claim claim, @Val Rollup before, PersonStore people, Audit audit,
            RollupService rollups) {
        audit.record(line("CLAIM_EDITED", input, people.find(claim.getSheetId(), claim.getPersonId()), claim));
        rollups.record(claim.getSheetId(), input.user(), before);
    }

    static String line(String event, ClaimInput input, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + claim.getSheetId() + " by=" + input.user() + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Claim claim) {
        claim.setAmount(input.amount());
        claim.setDate(input.date());
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setEditedBy(input.user());
    }
}

