package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit of a claim that is no longer a draft: an open claim is voided and added anew instead. */
public class CheckClaimDraft {
    public void check(@Val Claim claim) throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot be edited");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit of a claim another user has locked by opening its editor. */
public class CheckClaimLock {
    public void check(@Val ClaimInput input, @Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (store.lockedByOther(claim, input.user() == null ? "" : input.user().trim())) {
            throw new InvalidSheetException("The claim is being edited by another user");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a change to a claim due by a date inside a closed period (the period a claim belongs to is the one its
 *  due-by falls in): editing it or moving it on. */
public class CheckClaimPeriod {
    public void check(@Val Claim claim, PeriodStore periods) throws InvalidSheetException {
        ClaimPeriods.refuseClosed(periods, claim.getSheetId(), claim.getDueBy());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Stores an edit of a draft, refusing it when another user moved the claim on first. */
public class SaveClaimEdit {
    public void save(@Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (!store.edit(claim)) {
            throw new InvalidSheetException("Only a DRAFT claim can be edited");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored claim edit: CLAIM_EDITED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>. */
public class AuditClaimEdited {
    public void audit(@Val ClaimInput input, @Val Claim claim, @Val Rollup before, PersonStore people, Audit audit,
            RollupService rollups) {
        audit.record(line("CLAIM_EDITED", input, people.find(claim.getSheetId(), claim.getPersonId()), claim));
        rollups.record(claim.getSheetId(), input.user(), before);
    }

    static String line(String event, ClaimInput input, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + claim.getSheetId() + " by=" + input.user() + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ClaimInput input, @Val Claim claim) {
        claim.setAmount(input.amount());
        claim.setDate(input.date());
        claim.setNote(input.note());
        claim.setCorrects(input.corrects());
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setEditedBy(input.user());
    }
}

