package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    /** A number with up to two decimals; negative for a correction. */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    /** A claim number: the sheet-wide 1, 2, ... or <period>-<n> / X-<n>. */
    private static final Pattern NUMBER = Pattern.compile("\\S{1,255}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimRequest request,
            SettingStore settings, Out<ClaimInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(check(sheetId, request, settings));
    }

    /** The claim form's rules on a typed claim, before anything is stored: the claim as it would be stored
     *  (a blank date is the entry date while it is set, else the sheet's today). */
    static ClaimInput check(String sheetId, ClaimRequest request, SettingStore settings) throws InvalidSheetException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number with up to two decimals");
        }
        String dateText = request.date() == null ? "" : request.date().trim();
        LocalDate date;
        try {
            date = dateText.isEmpty() ? settings.claimDate(sheetId.trim()) : LocalDate.parse(dateText);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + dateText);
        }
        String note = request.note() == null ? "" : request.note().trim();
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String correctsText = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (!NUMBER.matcher(correctsText).matches()) {
                throw new InvalidSheetException("A negative amount must name the number of the settled claim it corrects");
            }
            corrects = correctsText;
        } else if (!correctsText.isEmpty()) {
            throw new InvalidSheetException("Only a negative amount corrects a claim");
        }
        String ref = request.ref() == null ? "" : request.ref().trim();
        return new ClaimInput(value, date, note, request.user(), corrects, ref.isEmpty() ? null : ref,
                Tags.normalise(request.tags()));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated claim add or edit: the date already defaulted to the sheet's today; {@code corrects}
 *  the number of the claim a correction (a negative amount) corrects, null for any other claim;
 *  {@code ref} the external reference, spaces around it removed, null when none was given; {@code tags} its
 *  tags (see {@link Tags}), null when none were given. */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String user, String corrects, String ref,
        String tags) {

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String user, String corrects, String ref) {
        this(amount, date, note, user, corrects, ref, null);
    }

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String user, String corrects) {
        this(amount, date, note, user, corrects, null);
    }

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String user) {
        this(amount, date, note, user, null);
    }

    /** Whether this is a correction: a negative amount. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimStore store, Out<Claim> claimOut) throws InvalidSheetException {
        Claim claim = null;
        try {
            claim = store.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such claim
        }
        if (claim == null) {
            throw new InvalidSheetException("No such claim: " + claimId);
        }
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;

/** A claim as the front end reads it: the amount with two decimals, the date as yyyy-MM-dd,
 *  the status by name, the number as given when opened (1, 2, ... or <period>-<n> / X-<n>; null when it has none), the due fixed when
 *  settled with two decimals (null when it has none, so its due is worked out from the current rate), and who opened it
 *  (null until opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound while it had none), whether it was bound to n/a (its rate had ended), and the number of the claim a correction corrects
 *  (null when it is not a correction), and the date its live figures round by (its own, or for a
 *  correction that of the claim it corrects), and the date it is due by, fixed when it was added, and its status log
 *  (see {@link ClaimLogStore}), oldest first, and whether it is deferred on the sheet's today (see
 *  {@link Claim#isDeferredOn}; a VOID claim deferred until after it shows as deferred too) and the date it was deferred until (null when never deferred), and how many proofs it has, and the number of the claim it was
 *  split off (null when it was not split off another), and whether it is a late entry (added while its period was soft-closed),
 *  and the last date it was reminded on (null when never reminded), and its external reference (null when it has none), and its tags, sorted (empty when it has none),
 *  and the reason it was voided with (null when none), and its comments (see {@link ClaimCommentStore}), oldest first,
 *  and the bulk settle batch it was settled in (null when settled one at a time, or not settled). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status, String number,
        String due, String openedBy, boolean stated, String statedDue, boolean statedNa, String corrects, String roundsBy,
        String dueBy, List<String> log, boolean deferred, String deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, String remindedOn, String ref, List<String> tags, String voidReason,
        List<String> comments, Long batch) {
    public static ClaimResponse from(Claim c) {
        return from(c, c.getDate());
    }

    public static ClaimResponse from(Claim c, Rounding rounding) {
        return from(c, rounding.date(c));
    }

    public static ClaimResponse from(Claim c, LocalDate roundsBy) {
        return new ClaimResponse(c.getId(), c.getPersonId(), c.getAmount().toPlainString(), c.getDate().toString(),
                c.getNote(), c.getStatus().name(), c.getNumber(),
                c.getSettledDue() == null ? null : c.getSettledDue().setScale(2).toPlainString(),
                c.getOpenedBy(), c.isStated(),
                c.getStatedDue() == null ? null : c.getStatedDue().setScale(2).toPlainString(), c.isStatedNa(),
                c.getCorrects(), roundsBy.toString(), c.getDueBy().toString(), List.of(),
                false, c.getDeferredUntil() == null ? null : c.getDeferredUntil().toString(), c.getProofs(),
                c.getSplitFrom(), c.isLateEntry(), c.getRemindedOn() == null ? null : c.getRemindedOn().toString(), c.getRef(),
                Tags.list(c.getTags()), c.getVoidReason(), List.of(), c.getBatch());
    }

    /** The same claim with its status log lines, oldest first. */
    public ClaimResponse withLog(List<String> lines) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, lines, deferred, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason, comments, batch);
    }

    /** The same claim with its comment lines, oldest first. */
    public ClaimResponse withComments(List<String> lines) {
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, log, deferred, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason, lines, batch);
    }

    /** The same claim, deferred when OPEN, or VOID (a voided claim still shows its deferral, though it counts
     *  nowhere), and deferred until a date after the sheet's {@code today}. */
    public ClaimResponse on(LocalDate today) {
        boolean now = (ClaimStatus.OPEN.name().equals(status) || ClaimStatus.VOID.name().equals(status))
                && deferredUntil != null && today != null
                && today.toString().compareTo(deferredUntil) < 0;
        return new ClaimResponse(id, personId, amount, date, note, status, number, due, openedBy, stated, statedDue,
                statedNa, corrects, roundsBy, dueBy, log, now, deferredUntil, proofs, splitFrom, lateEntry, remindedOn, ref, tags, voidReason, comments, batch);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ClaimStore store, ClaimLogStore log, ClaimCommentStore comments, SheetStore sheets, ObjectResponse<ClaimResponse> response) {
        Claim corrected = claim.getCorrects() == null ? null
                : store.findByNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
        response.send(ClaimResponse.from(claim, corrected == null ? claim.getDate() : corrected.getDate()).withLog(log.lines(claim))
                .withComments(comments.lines(claim))
                .on(sheets.today(claim.getSheetId())));
    }
}

